import {
  CheckboxGroup as AriaCheckboxGroup,
  FieldError,
  Label,
  Text,
} from "react-aria-components";
import type {
  CheckboxGroupProps as AriaCheckboxGroupProps,
  ValidationResult,
} from "react-aria-components";
import type { ReactNode, Ref } from "react";
import { CheckboxIndicatorContext, CheckboxSizeContext, CheckboxVariantContext } from "./Checkbox";
import type { CheckboxGroupIndicator, CheckboxGroupVariant, CheckboxSize } from "./Checkbox";
import "./CheckboxGroup.css";

type CheckboxGroupOrientation = "vertical" | "horizontal";

export interface CheckboxGroupProps
  extends Omit<AriaCheckboxGroupProps, "className" | "children"> {
  /**
   * How each option draws its row, as RadioGroup's `variant` does. `standard`: the box and its
   * label on the page, the options flush. `filled`: every option is a box on the neutral fill,
   * parted from the next, and a checked one takes the selection fill and a brand edge, for a short
   * set of answers a person picks several of (a questionnaire step). The check stays in both, so
   * the choice is never colour alone.
   *
   * @default "standard"
   */
  variant?: CheckboxGroupVariant;
  /**
   * Size axis for the group's own text and every checkbox in it: the group relays it to its
   * checkboxes, and inside a group it wins over a checkbox's own `size`.
   *
   * @default "medium"
   */
  size?: CheckboxSize;
  /**
   * Visual item direction, the group's second visual axis after `size` (contract §5).
   *
   * Look only, so it is **not** forwarded to React Aria: `CheckboxGroup` reads no orientation
   * (verified — the primitive never references it), and `aria-orientation` is not applicable to
   * the `role="group"` it renders, since each checkbox is independently tab-focusable rather
   * than arrow-navigated. Contrast `RadioGroup`, where the prop drives real behaviour.
   *
   * @default "vertical"
   */
  orientation?: CheckboxGroupOrientation;
  /**
   * How each option marks that it is checked. `box`: a square box before the label. `check`: the
   * label first and a round check at the row's trailing edge, an outline circle at rest and a
   * brand-filled circle with a check when chosen, the row spanning its column; the look of a phone's
   * multi-select list, where the trailing edge is where a choice is confirmed.
   *
   * @default "box"
   */
  indicator?: CheckboxGroupIndicator;
  /** Group label. */
  label?: string;
  /**
   * A `ContextualHelp` shown after the label, for a note the reader opens when they need it rather
   * than a `description` that is always on screen.
   */
  contextualHelp?: ReactNode;
  /** Helper text below the group. */
  description?: string;
  /** Message shown when validation fails. */
  errorMessage?: string | ((v: ValidationResult) => string);
  /** Checkbox items. */
  children?: ReactNode;
  /** Additional class. sd-checkbox-group is always retained. */
  className?: string;
  /** Passed to the underlying div DOM node. */
  ref?: Ref<HTMLDivElement>;
}

export function CheckboxGroup({
  variant = "standard",
  size = "medium",
  orientation = "vertical",
  indicator = "box",
  label,
  contextualHelp,
  description,
  errorMessage,
  children,
  className,
  ...props
}: CheckboxGroupProps) {
  return (
    <AriaCheckboxGroup
      {...props}
      className={className ? `sd-checkbox-group ${className}` : "sd-checkbox-group"}
      data-orientation={orientation}
    >
      {contextualHelp ? (
        <div className="sd-checkbox-group__label-group">
          {label && <Label className={`sd-checkbox-group__label sd-type-label-${size}`}>{label}</Label>}
          {contextualHelp}
        </div>
      ) : (
        label && (
          <Label className={`sd-checkbox-group__label sd-type-label-${size}`}>
            {label}
          </Label>
        )
      )}
      <div className="sd-checkbox-group__items" data-orientation={orientation} data-variant={variant}>
        <CheckboxVariantContext.Provider value={variant}>
          <CheckboxIndicatorContext.Provider value={indicator}>
            <CheckboxSizeContext.Provider value={size}>{children}</CheckboxSizeContext.Provider>
          </CheckboxIndicatorContext.Provider>
        </CheckboxVariantContext.Provider>
      </div>
      {description && (
        <Text
          slot="description"
          className={`sd-checkbox-group__description sd-type-caption-${size}`}
        >
          {description}
        </Text>
      )}
      <FieldError className={`sd-checkbox-group__error sd-type-caption-${size}`}>
        {errorMessage}
      </FieldError>
    </AriaCheckboxGroup>
  );
}

.sd-checkbox-group {
  display: flex;
  flex-direction: column;
  gap: var(--sd-checkbox-group-gap);
}
/* Options in a row are parted inline, so the label takes the field-label step above them. */
.sd-checkbox-group[data-orientation="horizontal"] {
  gap: var(--sd-checkbox-group-gap-horizontal);
}

/* label-group — present only with `contextualHelp`: the label and its help trigger share one row. */
.sd-checkbox-group__label-group {
  display: flex;
  align-items: center;
  gap: var(--sd-checkbox-group-label-group-gap);
}

.sd-checkbox-group__label {
  padding-inline: var(--sd-checkbox-group-text-padding-inline);
  color: var(--sd-checkbox-group-label-foreground);
}

.sd-checkbox-group__items {
  display: flex;
  gap: var(--sd-checkbox-group-items-gap);
}
.sd-checkbox-group__items[data-orientation="vertical"] {
  flex-direction: column;
}
.sd-checkbox-group__items[data-orientation="horizontal"] {
  flex-direction: row;
  flex-wrap: wrap;
  column-gap: var(--sd-checkbox-group-items-gap-horizontal);
  row-gap: var(--sd-checkbox-group-items-row-gap-horizontal);
}
/* filled: each option is its own box, so the options part by a gap (RadioGroup's filled set). */
.sd-checkbox-group__items[data-variant="filled"] {
  gap: var(--sd-checkbox-group-items-gap-filled);
}

.sd-checkbox-group__description {
  padding-inline: var(--sd-checkbox-group-text-padding-inline);
  color: var(--sd-checkbox-group-description-foreground);
}

.sd-checkbox-group__error {
  padding-inline: var(--sd-checkbox-group-text-padding-inline);
  color: var(--sd-checkbox-group-error-foreground);
}
